const requireUser = async (auth) => { const { rows } = await pool.query('SELECT u.id,u.email,u.role,p.full_name,i.document_number,i.section_id,i.grade_id,i.course_id,i.course,e.section_id AS enrollment_section_id,e.grade_id AS enrollment_grade_id,e.course_id AS enrollment_course_id,s.name AS section_name,g.name AS grade_name,c.name AS course_name FROM quickbite.users u JOIN quickbite.profiles p ON p.user_id=u.id LEFT JOIN quickbite.user_identity i ON i.user_id=u.id LEFT JOIN quickbite.student_enrollments e ON e.user_id=u.id LEFT JOIN quickbite.academic_sections s ON s.id=COALESCE(e.section_id,i.section_id) LEFT JOIN quickbite.academic_grades g ON g.id=COALESCE(e.grade_id,i.grade_id) LEFT JOIN quickbite.academic_courses c ON c.id=COALESCE(e.course_id,i.course_id) WHERE u.id=$1 AND u.active',[auth.sub]); if(!rows[0]) throw new Error('invalid_token'); return rows[0]; };
