function colombiaClock(){
  const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Bogota',weekday:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).formatToParts(new Date());
  const get=(type)=>Number(parts.find((part)=>part.type===type)?.value??0);
  return {weekday:get('weekday') % 7,time:`${String(get('hour')).padStart(2,'0')}:${String(get('minute')).padStart(2,'0')}:${String(get('second')).padStart(2,'0')}`};
}
async function studentRecessStatus(userId){
  const enrollment=await pool.query('SELECT section_id,grade_id,course_id FROM quickbite.student_enrollments WHERE user_id=$1',[userId]);
  const current=enrollment.rows[0];
  if(!current) return {allowed:true,reason:'no_academic_assignment',schedule:null};
  const clock=colombiaClock();
  const result=await pool.query('SELECT s.id,s.name,s.weekday,s.start_time,s.end_time,s.active,s.priority,s.notes,t.section_id,t.grade_id,t.course_id FROM quickbite.recess_schedules s JOIN quickbite.recess_schedule_targets t ON t.recess_schedule_id=s.id WHERE s.active=true AND s.weekday=$1 AND (t.course_id=$2 OR t.grade_id=$3 OR t.section_id=$4) ORDER BY s.priority DESC,s.start_time',[clock.weekday,current.course_id,current.grade_id,current.section_id]);
  const activeSchedule=result.rows.find((row)=>String(row.start_time).slice(0,8)<=clock.time && clock.time<=String(row.end_time).slice(0,8));
  if(activeSchedule) return {allowed:true,reason:'within_recess',schedule:activeSchedule};
  if(result.rows.length) return {allowed:false,reason:'outside_recess_window',schedule:result.rows[0]};
  return {allowed:true,reason:'no_schedule_today',schedule:null};
}
const isUuid = (value) => typeof value === 'string' && /^[0-9a-f-]{36}$/i.test(value);
