const passwordHash = (value) => { const salt=randomBytes(16).toString('hex'); const digest=scryptSync(String(value),salt,64).toString('hex'); return `${salt}:${digest}`; };
const parseCookies = (request) => Object.fromEntries(String(request.headers.cookie ?? '').split(';').filter(Boolean).map((item)=>{const i=item.indexOf('=');return i<0?[item.trim(),'']:[item.slice(0,i).trim(),decodeURIComponent(item.slice(i+1))]}));
const publicOrigin = (request) => (process.env.PUBLIC_APP_URL?.replace(/\/$/,'') ?? ((request.headers['x-forwarded-proto'] ?? 'http') + '://' + request.headers.host));
const authCookie = (name,value,maxAge,secure=true) => name + '=' + encodeURIComponent(value) + '; Max-Age=' + maxAge + '; Path=/; SameSite=Lax' + (secure?'; Secure':'') + '; HttpOnly';
