export async function handler(request,response){const requestId=randomUUID();const origin=request.headers.origin;if(origin&&origins.has(origin)){response.setHeader('access-control-allow-origin',origin);response.setHeader('access-control-allow-credentials','true');}response.setHeader('vary','Origin');response.setHeader('access-control-allow-headers','authorization,content-type');response.setHeader('access-control-allow-methods','GET,POST,PUT,PATCH,DELETE,OPTIONS');if(request.method==='OPTIONS')return response.writeHead(204).end();try{await coreAcademicSchemaReady;await route(request,response,requestId);}catch(error){const known=['missing_token','invalid_token','expired_token'];const known403=['user_inactive','google_internal_account_not_allowed','firebase_role_mismatch','google_role_not_allowed'];const status=known.includes(error.message)?401:known403.includes(error.message)?403:error.statusCode===403?403:error.message==='invalid_json'?400:500;console.error(JSON.stringify({requestId,message:error.message}));json(response,status,{error:status===500?'internal_error':error.message},requestId);}} if(!process.env.VERCEL){http.createServer(handler).listen(port,()=>console.log(`QuickBite API listening on ${port}`));}